/* Get the field and value of the current item we are iterating. This should
 * be called immediately after streamIteratorGetID(), and for each field
 * according to the number of fields returned by streamIteratorGetID().
 * The function populates the field and value pointers and the corresponding
 * lengths by reference, that are valid until the next iterator call, assuming
 * no one touches the stream meanwhile. */
void streamIteratorGetField(streamIterator *si, unsigned char **fieldptr, unsigned char **valueptr, int64_t *fieldlen, int64_t *valuelen) {
    if (si->entry_flags & STREAM_ITEM_FLAG_SAMEFIELDS) {
        *fieldptr = lpGet(si->master_fields_ptr,fieldlen,si->field_buf);
        si->master_fields_ptr = lpNext(si->lp,si->master_fields_ptr);
    } else {
        *fieldptr = lpGet(si->lp_ele,fieldlen,si->field_buf);
        si->lp_ele = lpNext(si->lp,si->lp_ele);
    }
    *valueptr = lpGet(si->lp_ele,valuelen,si->value_buf);
    si->lp_ele = lpNext(si->lp,si->lp_ele);
}

/* Remove the current entry from the stream: can be called after the
 * GetID() API or after any GetField() call, however we need to iterate
 * a valid entry while calling this function. Moreover the function
 * requires the entry ID we are currently iterating, that was previously
 * returned by GetID().
 *
 * Note that after calling this function, next calls to GetField() can't
 * be performed: the entry is now deleted. Instead the iterator will
 * automatically re-seek to the next entry, so the caller should continue
 * with GetID(). */
void streamIteratorRemoveEntry(streamIterator *si, streamID *current) {
    unsigned char *lp = si->lp;
    int64_t aux;

    /* We do not really delete the entry here. Instead we mark it as
     * deleted flagging it, and also incrementing the count of the
     * deleted entries in the listpack header.
     *
     * We start flagging: */
    int flags = lpGetInteger(si->lp_flags);
    flags |= STREAM_ITEM_FLAG_DELETED;
    lp = lpReplaceInteger(lp,&si->lp_flags,flags);

    /* Change the valid/deleted entries count in the master entry. */
    unsigned char *p = lpFirst(lp);
    aux = lpGetInteger(p);

    if (aux == 1) {
        /* If this is the last element in the listpack, we can remove the whole
         * node. */
        lpFree(lp);
        raxRemove(si->stream->rax,si->ri.key,si->ri.key_len,NULL);
    } else {
        /* In the base case we alter the counters of valid/deleted entries. */
        lp = lpReplaceInteger(lp,&p,aux-1);
        p = lpNext(lp,p); /* Seek deleted field. */
        int64_t v;
        unsigned char *ele = lpGet(p,&v,NULL);
        if (ele == NULL) {
            aux = v;
        } else if (v == 1 && ele[0] >= '0' && ele[0] <= '9') {
            aux = ele[0] - '0';
        } else {
            long long ll;
            int ret = string2ll((char*)ele,v,&ll);
            serverAssert(ret != 0);
            aux = ll;
        }
        lp = lpReplaceInteger(lp,&p,aux+1);

        /* Update the listpack with the new pointer. */
        if (si->lp != lp)
            raxInsert(si->stream->rax,si->ri.key,si->ri.key_len,lp,NULL);
    }

    /* Update the number of entries counter. */
    si->stream->length--;

    /* Re-seek the iterator to fix the now messed up state. */
    streamID start, end;
    uint64_t raw_id[2];
    if (si->rev) {
        memcpy(raw_id,si->start_key,sizeof(raw_id));
        end = *current;
    } else {
        memcpy(raw_id,si->end_key,sizeof(raw_id));
        start = *current;
    }
#if (BYTE_ORDER != BIG_ENDIAN)
    unsigned char *x = (unsigned char *)raw_id, t;
    t = x[0]; x[0] = x[7]; x[7] = t;
    t = x[1]; x[1] = x[6]; x[6] = t;
    t = x[2]; x[2] = x[5]; x[5] = t;
    t = x[3]; x[3] = x[4]; x[4] = t;
    x = (unsigned char *)(raw_id + 1);
    t = x[0]; x[0] = x[7]; x[7] = t;
    t = x[1]; x[1] = x[6]; x[6] = t;
    t = x[2]; x[2] = x[5]; x[5] = t;
    t = x[3]; x[3] = x[4]; x[4] = t;
#endif
    if (si->rev) {
        start.ms = raw_id[0];
        start.seq = raw_id[1];
    } else {
        end.ms = raw_id[0];
        end.seq = raw_id[1];
    }

    /* Drop the current radix iterator before rebuilding the cursor. */
    if (si->ri.key != si->ri.key_static_string) zfree(si->ri.key);
    if (si->ri.stack.stack != si->ri.stack.static_items) zfree(si->ri.stack.stack);

    /* Encode the rebuilt range as 128-bit big endian keys. */
    uint64_t encoded[2];
    encoded[0] = htonu64(start.ms);
    encoded[1] = htonu64(start.seq);
    memcpy(si->start_key,encoded,sizeof(encoded));
    encoded[0] = htonu64(end.ms);
    encoded[1] = htonu64(end.seq);
    memcpy(si->end_key,encoded,sizeof(encoded));

    si->ri.flags = RAX_ITER_EOF;
    si->ri.rt = si->stream->rax;
    si->ri.key_len = 0;
    si->ri.key = si->ri.key_static_string;
    si->ri.key_max = RAX_ITER_STATIC_LEN;
    si->ri.data = NULL;
    si->ri.node_cb = NULL;
    si->ri.stack.stack = si->ri.stack.static_items;
    si->ri.stack.items = 0;
    si->ri.stack.maxitems = RAX_STACK_STATIC_ITEMS;
    si->ri.stack.oom = 0;

    if (!si->rev) {
        if (start.ms || start.seq) {
            raxSeek(&si->ri,"<=",(unsigned char*)si->start_key,
                    sizeof(si->start_key));
            if (si->ri.flags & RAX_ITER_EOF)
                raxSeek(&si->ri,"^",NULL,0);
        } else {
            raxSeek(&si->ri,"^",NULL,0);
        }
    } else {
        if (end.ms || end.seq) {
            raxSeek(&si->ri,"<=",(unsigned char*)si->end_key,
